body.raw:
{
  "query": "query SingleRun($id: ID!) {
  pipelineRun(id: $id) {
    id
    repoUrl
    branch
    status
    totalIssuesFound
    totalIssuesFixed
    totalFalsePositives
    prUrl
    prBranch
    errorMessage
    startedAt
    completedAt
    findings {
      filePath
      lineNumber
      issueType
      severity
      confidence
      status
      description
      fixedCode
      commitMessage
      criticReasoning
    }
  }
}",
  "variables": {
    "id": "{{runId}}"
  }
}

{
  "query": "query FixedFindings {
  allRuns {
    id
    repoUrl
    status
    prUrl
    findings {
      filePath
      lineNumber
      issueType
      severity
      status
      originalCode
      fixedCode
      commitMessage
    }
  }
}"

{
  "query": "query RunSummary {
  allRuns {
    id
    status
    totalIssuesFound
    totalIssuesFixed
    totalFalsePositives
    startedAt
    completedAt
  }
}"

{
  "query": "query RunResults($id: ID!) {
  pipelineRun(id: $id) {
    id status prUrl
    totalIssuesFound totalIssuesFixed totalFalsePositives
    findings {
      filePath lineNumber issueType severity confidence status
      description fixedCode commitMessage criticReasoning
    }
  }
}",
  "variables": { "id": "{{runId}}" }
}
